static void folds(void) {
    int i, bad;
    bad = 0;
    for (i = 0; i < N; i++)
        bad += differs(&E_add[0][i], &F_add[i], sizeof F_add[i], E_add[0][i].fl) != 0;
    report("fold_add ", bad);
    bad = 0;
    for (i = 0; i < N; i++)
        bad += differs(&E_sub[0][i], &F_sub[i], sizeof F_sub[i], E_sub[0][i].fl) != 0;
    report("fold_sub ", bad);
    bad = 0;
    for (i = 0; i < N; i++)
        bad += differs(&E_mul[0][i], &F_mul[i], sizeof F_mul[i], E_mul[0][i].fl) != 0;
    report("fold_mul ", bad);
    bad = 0;
    for (i = 0; i < N; i++)
        bad += differs(&E_div[0][i], &F_div[i], sizeof F_div[i], E_div[0][i].fl) != 0;
    report("fold_div ", bad);
    bad = 0;
    for (i = 0; i < N; i++)
        bad += differs(&E_lt[0][i], &F_lt[i], sizeof F_lt[i], E_lt[0][i].fl) != 0;
    report("fold_lt ", bad);
    bad = 0;
    for (i = 0; i < N; i++)
        bad += differs(&E_eq[0][i], &F_eq[i], sizeof F_eq[i], E_eq[0][i].fl) != 0;
    report("fold_eq ", bad);
    bad = 0;
    for (i = 0; i < N; i++)
        if (E_to_ll[0][i].fl % 2 == 0)
            bad += differs(&E_to_ll[0][i], &F_to_ll[i], sizeof F_to_ll[i], E_to_ll[0][i].fl) != 0;
    report("fold_to_ll ", bad);
}

int main(void) {
    t_add();
    t_sub();
    t_mul();
    t_div();
    t_fma();
    t_sqrt();
    t_remainder();
    t_fmod();
    t_quantize();
    t_lt();
    t_eq();
    t_rint();
    t_nearbyint();
    t_floor();
    t_ceil();
    t_trunc();
    t_round();
    t_roundeven();
    t_nextup();
    t_nextdown();
    t_to_ll();
    t_from_ll();
    t_to_double();
    t_to_float();
    t_from_double();
    t_to_d32();
    t_to_d64();
    folds();
    return 0;
}
